@extends('layouts.admin') @section('title','Inventario y catálogo') @section('content')<p><a class="button" href="{{ route('admin.products.create') }}">Nuevo producto</a> <a class="button secondary" href="{{ route('admin.categories') }}">Gestionar colecciones</a></p><section class="panel"><table class="table"><tr><th>Producto</th><th>SKU</th><th>Colección</th><th>Precio</th><th>Stock</th><th>Estado</th><th></th></tr>@foreach($products as $product)<tr><td><b>{{ $product->name }}</b></td><td>{{ $product->sku ?: '—' }}</td><td>{{ $product->category->name }}</td><td>${{ number_format($product->price,0,',','.') }}</td><td class="{{ $product->stock <= $product->low_stock_threshold ? 'danger' : '' }}">{{ $product->stock }}</td><td><span class="tag">{{ $product->is_active ? 'Activo' : 'Oculto' }}</span></td><td><a href="{{ route('admin.products.edit',$product) }}">Editar</a></td></tr>@endforeach</table>{{ $products->links() }}</section>@endsection
